package net.officefloor.hq.app.role;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A role given to a user name on a sheet, recorded on the sheet's today then: the role the user had
 *  at the end of a day is the last one recorded on or before it. */
@Entity
@Table(name = "role_revision")
public class RoleRevision {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "user_name", nullable = false)
    private String userName;

    @Column(name = "role", nullable = false)
    private String role;

    /** The sheet's today when the role was given. */
    @Column(name = "recorded_on", nullable = false)
    private LocalDate recordedOn;

    protected RoleRevision() {
    }

    public RoleRevision(String sheetId, String userName, String role, LocalDate recordedOn) {
        this.sheetId = sheetId;
        this.userName = userName;
        this.role = role;
        this.recordedOn = recordedOn;
    }

    public String getRole() {
        return role;
    }

    public LocalDate getRecordedOn() {
        return recordedOn;
    }
}
package net.officefloor.hq.app.role;

import java.time.LocalDate;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RoleRevisionRepository extends JpaRepository<RoleRevision, Long> {

    /** The last role given to a user name on or before a day. */
    Optional<RoleRevision> findFirstBySheetIdAndUserNameAndRecordedOnLessThanEqualOrderByRecordedOnDescIdDesc(
            String sheetId, String userName, LocalDate day);
}
package net.officefloor.hq.app.role;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.AsOfGuard;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/roles")
@Validated
public class RoleController {

    /** What the screen shows of a role given to a user name. */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole role) {
            return new RoleView(role.getUserName(), role.getRole());
        }
    }

    /** The role a user acts in on the sheet. */
    public record MyRoleView(String role) {
    }

    /** The role form: a role of clerk, steward, viewer or restricted. */
    public record RoleForm(@NotNull @Pattern(regexp = "\\s*(clerk|steward|viewer|restricted)\\s*") String role) {
    }

    private final RoleService service;

    public RoleController(RoleService service) {
        this.service = service;
    }

    @GetMapping
    public List<RoleView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(RoleView::of).toList();
    }

    /** The role the signed-in user acts in on the sheet now, or as they had it at the end of the
     *  as-of day when one is given. */
    @GetMapping("/me")
    public MyRoleView mine(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        String sheet = sheetId.trim();
        String name = user.trim();
        return new MyRoleView(asOf == null ? service.roleOf(sheet, name) : service.roleOn(sheet, name, asOf));
    }

    @PutMapping("/{userName}")
    public RoleView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @NotBlank @Size(max = 100) String userName,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RoleForm form) {
        return RoleView.of(service.set(sheetId.trim(), user.trim(), userName.trim(), form.role().trim()));
    }
}
package net.officefloor.hq.app.role;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** The role a user name has on a sheet; a name with none is a clerk. A viewer may change nothing. */
@Entity
@Table(name = "sheet_role")
public class SheetRole {

    /** The role every name has until it is given another. */
    public static final String CLERK = "clerk";
    /** A steward may settle a claim of any due. */
    public static final String STEWARD = "steward";
    /** A viewer sees every screen and figure and may change nothing. */
    public static final String VIEWER = "viewer";
    /** A restricted user lists only the people of the crews their person leads or belongs to, and
     *  that person; every other figure is still over the whole sheet. */
    public static final String RESTRICTED = "restricted";

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "user_name", nullable = false)
    private String userName;

    @Column(name = "role", nullable = false)
    private String role;

    protected SheetRole() {
    }

    public SheetRole(String sheetId, String userName, String role) {
        this.sheetId = sheetId;
        this.userName = userName;
        this.role = role;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getUserName() {
        return userName;
    }

    public String getRole() {
        return role;
    }

    public void setRole(String role) {
        this.role = role;
    }
}
package net.officefloor.hq.app.watch;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.AsOfGuard;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
public class WatchController {

    /** A person the signed-in user watches, by id. */
    public record WatchView(long id, long personId) {
        static WatchView of(Watch watch) {
            return new WatchView(watch.getId(), watch.getPersonId());
        }
    }

    private final WatchService service;

    public WatchController(WatchService service) {
        this.service = service;
    }

    @GetMapping("/api/sheets/{sheetId}/watches")
    public List<WatchView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        return service.list(sheetId.trim(), user.trim()).stream()
                .filter(w -> asOf == null || w.getStartedOn() == null || !w.getStartedOn().isAfter(asOf))
                .map(WatchView::of).toList();
    }

    @PostMapping("/api/sheets/{sheetId}/people/{personId}/watch")
    @ResponseStatus(HttpStatus.CREATED)
    public WatchView watch(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return WatchView.of(service.watch(sheetId.trim(), user.trim(), personId));
    }

    @DeleteMapping("/api/sheets/{sheetId}/people/{personId}/watch")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void unwatch(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        service.unwatch(sheetId.trim(), user.trim(), personId);
    }
}

